% conformance testing framework of Peter Szabo and Peter Szeredi.
% Generated by lang/stralog/tests/mkiso.py: v(Name, Expected, Goal).


v(commons_findall_4_01, true(S == [1,2,3]), (findall(X, (X=1;X=2), S, [3]))).
v(commons_findall_4_03, true(L == [0]), (findall(_X, fail, L, [0]))).
v(commons_findall_4_04, true(S == [1,1]), (findall(X, (X=1;X=1), S, []))).
v(commons_findall_4_05, false, (findall(X, (X=2;X=1), [1,2], _))).
v(commons_findall_4_07, true(L == [1,2,3]), (findall(X, (X=1;X=2), L, [Y]), Y = 3)).
v(commons_findall_4_08, error(instantiation_error), (findall(_X, _Goal, _S, _T))).
v(commons_findall_4_10, error(type_error(list,[A|1])), (findall(X, X=1, [A|1], _))).
v(commons_findall_4_11, error(type_error(list,12)), (findall(X, (X=2; X=1), 12, []))).
v(commons_findall_4_12, error(type_error(list,[A|1])), (findall(X, X=1, _, [A|1]))).
v(commons_findall_4_13, error(type_error(list,12)), (findall(X, (X=2; X=1), _, 12))).
v(commons_findall_4_15, ball(err), (findall(X, (X = 1; throw(err)), _, _))).
